import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv, {type ValidateFunction} from 'ajv';

const ajv = new Ajv({
  strict: false,
  validateFormats: false,
  useDefaults: false,
  coerceTypes: false,
  addUsedSchema: false,
});

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validatorCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ValidateFunction | undefined;

    if (typeof definition !== 'function') {
      try {
        staticValidator = ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Failed to compile schema for tool ${resolved.name}: ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      staticValidator,
    });
  }

    expect(() => registry.register(invalidSchema, async () => 'ok')).toThrow(/broken-tool/);
  });

  it('validates against the schema current at that call for a function-valued tool definition', async () => {
    const registry = new ToolRegistry();
    let schemaType = 'string';
    const definitionSource = () => ({
      name: 'dynamic-tool',
      description: 'A tool with a dynamic schema',
      inputSchema: {
        type: 'object',
        properties: {
          val: {type: schemaType},
        },
        required: ['val'],
      },
    });

    const executor = vi.fn().mockResolvedValue('ok');
    registry.register(definitionSource, executor);

    // First call: schema requires string
    await registry.execute('dynamic-tool', {val: 'hello'});
    expect(executor).toHaveBeenCalledWith({val: 'hello'}, undefined);

    // Second call: schema requires string, but we pass number
    const response = await registry.execute('dynamic-tool', {val: 123});
    expect(response.result).toMatch(/val/);
    expect(response.result).toMatch(/string/);
    expect(executor).toHaveBeenCalledTimes(1);

    // Change schema to require number
    schemaType = 'number';
    await registry.execute('dynamic-tool', {val: 123});
    expect(executor).toHaveBeenCalledTimes(2);
    expect(executor).toHaveBeenLastCalledWith({val: 123}, undefined);
  });
});

