/** See {@link specs/hal-engine-tool-input-validation/spec.md} for validation and error contract. */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const resolved = this.resolveDefinition(tool.definitionSource);
  let validator = tool.staticValidator;

  if (!validator) {
    const cached = this.validatorCache.get(resolved.inputSchema);
    if (cached) {
      validator = cached;
    } else {
      validator = ajv.compile(resolved.inputSchema);
      this.validatorCache.set(resolved.inputSchema, validator);
    }
  }

  if (!validator(input)) {
    const errors = validator.errors || [];
    const errorDetail = errors
      .map(e => {
        const path = e.instancePath || 'input';
        if (e.keyword === 'required') {
          return `missing required property: ${e.params.missingProperty}`;
        }
        return `${path} ${e.message} (expected ${e.params.type || e.keyword})`;
      })
      .join('; ');

    log.warn('tool', 'validation failed', {name, errorDetail});
    return {result: `Validation failed: ${errorDetail}`};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);

