    expect(executor).toHaveBeenCalledTimes(2);
    expect(executor).toHaveBeenLastCalledWith({val: 123}, undefined);
  });

  it('compiles a static tool schema once and reuses it', async () => {
    const registry = new ToolRegistry();
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');

    registry.register(
      {
        name: 'static-tool',
        description: 'desc',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async () => 'ok'
